import {VoiceTrial,voiceError,parseSpeech} from './voice.js';
const labels={name:'Alimento',qty:'Cantidad',unit:'Unidad',date:'Fecha'};
export function voiceProposal(text){const p=parseSpeech(text),values={};if(p.name)values.name=p.name;if(Number.isFinite(p.qty)&&p.qty>0)values.qty=String(p.qty);if(p.unit)values.unit=p.unit;if(p.date)values.date=p.date;return {values,warnings:p.warnings};}
export function changedVoiceFields(values,current){return Object.keys(values).filter(k=>String(current[k]??'').trim()!==''&&String(current[k])!==String(values[k]));}
export const voiceFormHTML=()=>`<section class="voice-form" aria-label="Dictado opcional"><p class="hint">Dictado opcional. El navegador puede enviar el audio a su servicio de voz. No dictes datos de salud. Revisa siempre lo entendido; no se guarda automáticamente.</p><div class="dialog-actions"><button type="button" class="button secondary" id="food-mic">🎙 Dictar alimento</button><button type="button" class="button secondary" id="food-stop" disabled>Detener</button><button type="button" class="button secondary" id="food-voice-cancel" disabled>Cancelar dictado</button></div><p id="food-voice-status" class="hint" role="status" aria-live="polite">Micrófono apagado.</p><div id="food-voice-review" hidden><label>Texto entendido<textarea id="food-heard" rows="2" readonly></textarea></label><p id="food-voice-proposal"></p><p id="food-voice-warning" class="hint"></p><label id="food-voice-overwrite-label" class="checkbox-line" hidden><input type="checkbox" id="food-voice-overwrite">Confirmo sustituir los campos indicados por la propuesta.</label><button type="button" class="button secondary" id="food-voice-apply">Pasar al formulario para revisar</button></div></section>`;
export function bindFoodVoice(form,{factory,exposed=!!(window.SpeechRecognition||window.webkitSpeechRecognition),onApplied=()=>{}}={}){
 const q=id=>form.querySelector('#'+id),current=()=>Object.fromEntries(Object.keys(labels).map(k=>[k,q('lot-'+k).value]));
 let disposed=false,proposal=null,signature='',session;
 const submit=q('submit-lot'),previousDisabled=submit.disabled;
 const refresh=()=>{if(!proposal)return;const conflicts=changedVoiceFields(proposal.values,current()),next=JSON.stringify([proposal.values,current()]);if(signature!==next)q('food-voice-overwrite').checked=false;signature=next;q('food-voice-overwrite-label').hidden=!conflicts.length;q('food-voice-warning').textContent=[...proposal.warnings,conflicts.length?'Se sustituirán: '+conflicts.map(k=>labels[k]).join(', ')+'. Confírmalo o conserva lo escrito.':'Revisa todos los campos antes de guardar.'].join(' ');q('food-voice-apply').disabled=session.active||!!(conflicts.length&&!q('food-voice-overwrite').checked);return conflicts;};
 session=new VoiceTrial(factory||(()=>new (window.SpeechRecognition||window.webkitSpeechRecognition)()),s=>{
  if(disposed)return;const active=session.active;q('food-mic').disabled=!exposed||active;q('food-stop').disabled=!active;q('food-voice-cancel').disabled=!(active||s.text);submit.disabled=previousDisabled||active;
  q('food-voice-status').textContent=s.phase==='error'?voiceError(s.error):s.phase==='cancelled'?'Dictado cancelado. Se conserva lo escrito en el formulario.':s.phase==='starting'?'Solicitando el micrófono…':s.phase==='stopping'?'Deteniendo la escucha…':active?'Escuchando en español. Puedes continuar o pulsar Detener.':(s.endReason==='limit'?'Escucha terminada por el límite de dos minutos. ':s.endReason==='browser'?'El navegador ha terminado la escucha. ':'Escucha detenida. ')+'Revisa lo entendido; no se ha guardado nada.';
  q('food-heard').value=s.text;proposal=s.text?voiceProposal(s.text):null;q('food-voice-review').hidden=!proposal;q('food-voice-apply').disabled=active||!proposal;
  if(proposal){q('food-voice-proposal').textContent=Object.entries(proposal.values).map(([k,v])=>labels[k]+': '+(k==='date'?v.split('-').reverse().join('/'):v)).join(' · ');refresh();}
 });
 if(!exposed){q('food-mic').disabled=true;q('food-voice-status').textContent='Voz no disponible en este navegador. Puedes continuar con el formulario.';}
 q('food-voice-overwrite').onchange=refresh;
 q('food-mic').onclick=()=>session.start();q('food-stop').onclick=()=>session.stop();
 q('food-voice-cancel').onclick=()=>{session.cancel();proposal=null;q('food-heard').value='';q('food-voice-review').hidden=true;q('food-voice-cancel').disabled=true;};
 q('food-voice-apply').onclick=()=>{if(session.active||!proposal)return;const conflicts=refresh();if(conflicts.length&&!q('food-voice-overwrite').checked){q('food-voice-warning').textContent+=' No se ha sustituido ningún campo.';q('food-voice-overwrite').focus();return;}for(const [k,v] of Object.entries(proposal.values))q('lot-'+k).value=v;onApplied();q('food-voice-status').textContent='Propuesta pasada al formulario. Revisa nombre, cantidad, unidad, ubicación, fecha y tipo antes de guardar.';proposal=null;q('food-voice-review').hidden=true;q('food-voice-cancel').disabled=true;q('lot-name').focus();};
 const input=e=>{if(e.target.id.startsWith('lot-'))refresh();};form.addEventListener('input',input);form.addEventListener('change',input);
 const leave=()=>session.cancel(),visibility=()=>{if(document.hidden)leave();};window.addEventListener('pagehide',leave);document.addEventListener('visibilitychange',visibility);
 return {get active(){return session.active;},dispose(){if(disposed)return;disposed=true;session.cancel();form.removeEventListener('input',input);form.removeEventListener('change',input);window.removeEventListener('pagehide',leave);document.removeEventListener('visibilitychange',visibility);}};
}
